!function(){class t extends HTMLElement{constructor(){super()}static get observedAttributes(){return["speed"]}get speed(){return this.getAttribute("speed")}set speed(t){this.setAttribute("speed",t)}attributeChangedCallback(t,e,s){e!==s&&"speed"===t&&this._setDuration()}connectedCallback(){this._cloneData(),this._setDuration(),this._run()}_cloneData(){const t=this.firstElementChild,e=Math.round(this.offsetWidth/t.offsetWidth)+2;for(let s=0;s<e;s++){const e=this.firstElementChild.cloneNode(!0);e.ariaHidden="true",this.appendChild(e),t.remove()}}_setDuration(){const t=this.speed||4;let e=this.firstElementChild.offsetWidth/1e3*(10-t+1)*5,s=+(Math.round(e+"e+2")+"e-2");this.style.setProperty("--duration",s+"s")}_run(){for(const t of this.children)t.classList.add("__smi-animation-run")}}Shopify.designMode?customElements.get("smi-scrolling-text-2")||setTimeout((()=>{customElements.define("smi-scrolling-text-2",t)}),100):document.addEventListener("DOMContentLoaded",(()=>{customElements.get("smi-scrolling-text-2")||customElements.define("smi-scrolling-text-2",t)}))}();